sp_widget.client_script:
api.controller = function($scope) {
  var c = this;
  c.busy = false;

  c.act = function(action) {
    if (c.busy || !$scope.data.res) return;
    c.busy = true;
    $scope.data.notice = '';

    $scope.server.get({
      action: action,
      sysId:  $scope.data.res.sysId
    }).then(function(r) {
      $scope.data.res    = r.data.res;
      $scope.data.notice = r.data.notice;
      $scope.data.free   = r.data.free;
      c.busy = false;
    }, function() {
      $scope.data.notice = 'Something went wrong. Try again in a moment.';
      c.busy = false;
    });
  };

  $scope.act = c.act;
};

sp_widget.css:
.wrm-hero {
  display: flex;
  align-items: stretch;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-card);
  overflow: hidden;
  min-height: 190px;
  margin-bottom: 12px;
}

.wrm-hero .hero-body {
  flex: 1;
  padding: 22px 24px;
  min-width: 260px;
  overflow: hidden;
}

.wrm-hero .date {
  font-size: 11px;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.wrm-hero .greet { font-size: 24px; color: var(--ink); margin: 6px 0 4px; }
.wrm-hero .status { font-size: 14px; color: var(--ink-3); }
.wrm-hero .status strong { font-weight: 500; color: var(--ink); }

.wrm-hero .acts { display: flex; gap: 9px; flex-wrap: wrap; margin-top: 16px; }
.wrm-hero .btn {
  font-size: 13px;
  font-weight: 500;
  border: 0;
  padding: 9px 20px;
  border-radius: var(--r-pill);
  background: var(--clay);
  color: var(--on-clay);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.22);
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
}
.wrm-hero .btn:hover { background: var(--clay-press); color: var(--on-clay); text-decoration: none; }
.wrm-hero .btn:focus-visible { outline: 2px solid var(--clay); outline-offset: 3px; }
.wrm-hero .btn.ghost {
  background: transparent;
  color: var(--ink-2);
  box-shadow: inset 0 0 0 1px var(--line);
  padding: 9px 18px;
}
.wrm-hero .btn.ghost:hover { background: var(--surface-2); color: var(--ink); }

.wrm-hero .notice {
  font-size: 12px;
  color: var(--held-fg);
  background: var(--held-bg);
  padding: 8px 13px;
  border-radius: var(--r-soft);
  margin-top: 12px;
  display: inline-block;
}

.wrm-hero .hero-img {
  width: 38%;
  flex: none;
  height: 100%;
  min-height: 0;
  background: var(--surface-2);
}
.wrm-hero .hero-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.wrm-hero .hero-mosaic {
  width: 38%;
  flex: none;
  height: 100%;
  min-height: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  background: var(--surface-2);
}
.wrm-hero .hero-mosaic span { display: block; overflow: hidden; }
.wrm-hero .hero-mosaic img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

@media (max-width: 720px) {
  .wrm-hero { flex-direction: column; height: auto; }
  .wrm-hero .hero-img,
  .wrm-hero .hero-mosaic { width: 100%; height: 130px; }
}

sp_widget.script:
(function() {

  var WEEKDAYS = ['Sunday','Monday','Tuesday','Wednesday',
                  'Thursday','Friday','Saturday'];
  var MONTHS   = ['January','February','March','April','May','June','July',
                  'August','September','October','November','December'];

  var HOLDING = 'pending_check_in,checked_in';
  var CHECKIN_LEAD_MIN = 60;

  var nowMs    = new GlideDateTime().getNumericValue();
  var todayYmd = new GlideDateTime().getDisplayValue().split(' ')[0];
  var tp = todayYmd.split('-');

  // --- handle a check-in or check-out posted from the client ---
  data.notice = '';

  if (input && input.action && input.sysId) {
    var r = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
    if (r.get(input.sysId) && r.getValue('reserved_for') === gs.getUserID()) {

      if (input.action === 'checkin' &&
          r.getValue('reservation_status') === 'pending_check_in') {
        var st = r.getValue('work_start');
        var opens = st ? new GlideDateTime(st).getNumericValue() - (CHECKIN_LEAD_MIN * 60000) : 0;
        if (nowMs < opens) {
          // Show when check-in actually opens, not the start time,
          // and include the date unless it's today.
          var og = new GlideDateTime(st);
          og.addSeconds(-CHECKIN_LEAD_MIN * 60);
          var od = og.getDisplayValue().split(' ');
          var oTime = od[1].substring(0, 5);

          data.notice = (od[0] === todayYmd)
                      ? 'Check-in opens at ' + oTime + '.'
                      : 'Check-in opens ' + od[0] + ' at ' + oTime + '.';
        } else {
          r.setValue('reservation_status', 'checked_in');
          r.work_notes = 'Reservation checked in by ' + gs.getUserDisplayName();
          r.update();
        }
      }

      if (input.action === 'checkout' &&
          r.getValue('reservation_status') === 'checked_in') {
        r.setValue('reservation_status', 'checked_out');
        r.setValue('state', 3);
        r.work_notes = 'Reservation checked out by ' + gs.getUserDisplayName();
        r.update();
      }
    }
  }

  // --- greeting ---
  var u = gs.getUser();
  data.firstName = u.getFirstName() || u.getName();

  var hour = parseInt(new GlideDateTime().getDisplayValue().split(' ')[1].split(':')[0], 10);
  data.greeting = hour < 12 ? 'Good morning'
                : hour < 18 ? 'Good afternoon'
                            : 'Good evening';

  var td = new Date(Date.UTC(+tp[0], +tp[1] - 1, +tp[2]));
  data.dateLine = WEEKDAYS[td.getUTCDay()] + ' ' +
                  parseInt(tp[2], 10) + ' ' + MONTHS[+tp[1] - 1];

  function imageUrl(raw) {
    if (!raw) return '';
    return raw.indexOf('.') > -1
         ? (raw.charAt(0) === '/' ? raw : '/' + raw)
         : '/sys_attachment.do?sys_id=' + raw;
  }

  // --- this user's next live reservation ---
  data.res = null;
  data.heroImage = '';

  var gr = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
  gr.addQuery('reserved_for', gs.getUserID());
  gr.addQuery('reservation_status', 'IN', HOLDING);
  gr.orderBy('work_start');
  gr.setLimit(1);
  gr.query();

  if (gr.next()) {
    var sDisp = gr.getDisplayValue('work_start');
    var eDisp = gr.getDisplayValue('work_end');
    var sYmd  = sDisp ? sDisp.split(' ')[0] : '';
    var eYmd  = eDisp ? eDisp.split(' ')[0] : '';
    var status = gr.getValue('reservation_status');

    // Day name for a booking that isn't today.
    var dayName = '';
    if (sYmd) {
      var sp = sYmd.split('-');
      var sd = new Date(Date.UTC(+sp[0], +sp[1] - 1, +sp[2]));
      dayName = WEEKDAYS[sd.getUTCDay()];
    }

    // The hero image is the space you've booked.
    var wsId = gr.getValue('workspace');
    if (wsId) {
      var ws = new GlideRecord('x_1903615_worksp_0_workspace_options');
      if (ws.get(wsId)) data.heroImage = imageUrl(ws.getValue('image'));
    }

    data.res = {
      sysId:      gr.getUniqueValue(),
      workspace:  gr.getDisplayValue('workspace'),
      location:   gr.getDisplayValue('location'),
      startTime:  sDisp ? sDisp.split(' ')[1].substring(0, 5) : '',
      endTime:    eDisp ? eDisp.split(' ')[1].substring(0, 5) : '',
      dayName:    dayName,
      isToday:    sYmd <= todayYmd && eYmd >= todayYmd,
      checkedIn:  status === 'checked_in',
      canCheckIn: status === 'pending_check_in'
    };
  }

  // --- free count, and the mosaic shown when nothing is booked ---
  data.photos = [];

  var free = new GlideRecord('x_1903615_worksp_0_workspace_options');
  free.addQuery('status', 'available');
  free.query();
  data.free = free.getRowCount();

  // Several spaces share the same uploaded photo, so pick one per
  // type and never repeat an image — otherwise the mosaic is four
  // copies of the same picture.
  var seenImages = {};
  var seenTypes  = {};

  var pics = new GlideRecord('x_1903615_worksp_0_workspace_options');
  pics.addQuery('status', 'available');
  pics.addNotNullQuery('image');
  pics.orderBy('workspace_type');
  pics.query();

  while (pics.next() && data.photos.length < 4) {
    var raw = pics.getValue('image');
    var t   = pics.getValue('workspace_type');
    if (seenImages[raw] || seenTypes[t]) continue;

    var url = imageUrl(raw);
    if (url) {
      data.photos.push(url);
      seenImages[raw] = true;
      seenTypes[t] = true;
    }
  }

  // --- links ---
  data.bookUrl   = '?id=sc_cat_item&sys_id=fe1e919e93c6c3108c8874dcebba10d0';
  data.spacesUrl = '?id=wrm_spaces';
  data.resUrl    = '?id=wrm_reservations';
  data.helpUrl   = '?id=sc_cat_item&sys_id=d71f7be693d6c7108c8874dcebba10bb';

})();
